create table public.skill_graph_nodes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,role_slug text not null,skill_slug text not null,proficiency_score smallint check(proficiency_score between 0 and 100),confidence text not null check(confidence in ('low','medium','high')),evidence_strength smallint not null default 0,freshness_at timestamptz,calculation_version text not null,explanation jsonb not null,updated_at timestamptz not null default now(),unique(user_id,role_slug,skill_slug,calculation_version));
create table public.portfolio_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,item_type text not null check(item_type in ('project','credential','assessment','interview','work_experience','learning')),title text not null,summary text,skill_slugs text[] not null default '{}',source_ref text,verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected','expired')),visibility text not null default 'private' check(visibility in ('private','matched_employers','shared_link')),occurred_at timestamptz not null,created_at timestamptz not null default now());
alter table public.skill_graph_nodes enable row level security;alter table public.portfolio_items enable row level security;create policy "users read own skill graph" on public.skill_graph_nodes for select using(user_id=auth.uid());create policy "users manage portfolio items" on public.portfolio_items for all using(user_id=auth.uid()) with check(user_id=auth.uid());create index portfolio_timeline_idx on public.portfolio_items(user_id,occurred_at desc);create index skill_graph_role_idx on public.skill_graph_nodes(user_id,role_slug,updated_at desc);
